window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[114]={"id":"114","numero":114,"titre":"Exanthème et érythrodermie","objectifs":[{"id":"114-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un exanthème","contenu":"<table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td><span class=\"kw-def\">Érythème d’apparition <strong>brutale</strong> et <strong>transitoire</strong></span> lié à une vasodilatation vasculaire, qui s’<strong>efface à la vitropression</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Sémio</strong></td>\n            <td>Intensité variable, diffus ou de topographie spécifique, isolé ou associé à une symptomatologie variée.</td>\n          </tr>\n          <tr>\n            <td><strong>Énanthème</strong></td>\n            <td>Association possible à une <span class=\"kw-clinique\">atteinte muqueuse</span> = énanthème (<span class=\"kw-def\">purpura</span> du voile du palais, glossite, chéilite, langue framboisée).</td>\n          </tr>\n          <tr>\n            <td><strong>Gravité</strong></td>\n            <td>Le plus souvent <span class=\"kw-clinique\">bénin</span>, mais potentiellement <span class=\"kw-alerte\">grave</span> (toxidermie, méningococcémie, Kawasaki, <span class=\"kw-alerte\">choc</span> toxinique).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 165 — Oreillons · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0},{"id":"114-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une érythrodermie","contenu":"<table >\n        <thead><tr><th>Critère</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition clinique</strong></td>\n            <td><span class=\"kw-def\">Érythème confluant + desquamation</span> touchant l’ensemble des téguments (<strong>&gt;<span class=\"kw-chiffre\"> 90 %</span> de la surface corporelle</strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td><span class=\"kw-def\">Évolution prolongée &gt; 6 semaines</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Gravité</strong></td>\n            <td><span class=\"kw-alerte\">Urgence dermatologique 🔥</span> — prise en charge thérapeutique et étiologique immédiate.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Ne sont pas des érythrodermies :</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Éruption</span> érythémato-squameuse avec éléments multiples et diffus séparés par des <strong>intervalles de peau saine</strong></li>\n          <li>Exanthème ou nécrolyse épidermique avec décollement dont l’<span class=\"kw-clinique\">évolution</span> est <strong>aiguë</strong> (<span class=\"kw-alerte\">Lyell</span>, Stevens-Johnson)</li>\n        </ul>\n      </div>\n\n      <h4>Démarche en 3 temps</h4>\n      <ol>\n        <li>Reconnaître l’érythrodermie</li>\n        <li>Rechercher l’étiologie en vue d’un traitement spécifique</li>\n        <li>Apprécier la gravité immédiate et proposer une attitude thérapeutique symptomatique</li>\n      </ol>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 117 — <span class=\"kw-clinique\">Psoriasis</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"114-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître les trois types séméiologiques d’exanthème","contenu":"<p>Trois grandes formes séméiologiques à reconnaître au lit du patient. En pratique, des <strong>associations sont possibles</strong> selon la zone cutanée considérée.</p>\n\n      <table class=\"matrix\">\n        <thead>\n          <tr>\n            <th></th>\n            <th>Morbilliforme</th>\n            <th>Roséoliforme<br><span class=\"kw-chiffre\">(rubéoliforme)</span></th>\n            <th>Scarlatiniforme</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sémio</strong></td>\n            <td><span class=\"kw-clinique\">Maculo-papuleux</span></td>\n            <td>Macules</td>\n            <td><span class=\"kw-clinique\">Plaques / nappes diffuses</span></td>\n          </tr>\n          <tr>\n            <td><strong>Couleur</strong></td>\n            <td>Rouge</td>\n            <td>Rosé, pâle</td>\n            <td>Rouge vif ou plus sombre</td>\n          </tr>\n          <tr>\n            <td><strong>Relief</strong></td>\n            <td>Léger relief (papuleux)</td>\n            <td>Sans relief (ou minime)</td>\n            <td>Légèrement granité à la palpation</td>\n          </tr>\n          <tr>\n            <td><strong>Peau saine</strong></td>\n            <td>Peuvent <strong>confluer en plaques</strong> plus larges séparées par des intervalles de peau saine</td>\n            <td>Séparées les unes des autres (<em>intervalles de peau saine</em>)</td>\n            <td>D’un seul tenant : <strong>pas d’intervalle de peau saine</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 Collège de pédiatrie :</strong> les termes « morbilliforme », « scarlatiniforme »… sont <em>désuets</em> et doivent être abandonnés. Un même agent <span class=\"kw-etio\">viral</span> peut être responsable d’éruptions de divers types.\n      </div>\n\n      <h4>Orientation selon le mécanisme</h4>\n      <table class=\"matrix\">\n        <thead><tr><th></th><th>Infectieuse</th><th>Médicamenteuse</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Contexte</strong></td>\n            <td>\n              <strong>Contage</strong>, contexte épidémique ;<br>\n              Enfant → virus surtout ; Adulte → IST surtout (syphilis, <span class=\"kw-etio\">VIH</span>)\n            </td>\n            <td>Introduction d’un médicament <strong>5-14 j</strong> avant l’<span class=\"kw-clinique\">éruption</span></td>\n          </tr>\n          <tr>\n            <td><strong>Présentation</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Fièvre</span>, syndrome grippal ;<br>\n              <span class=\"kw-clinique\">Énanthème</span> ;<br>\n              <span class=\"kw-clinique\">Adénopathies</span>\n            </td>\n            <td>\n              <span class=\"kw-clinique\">Prurit</span> ;<br>\n              <span class=\"kw-clinique\">Polymorphisme</span> de l’<span class=\"kw-clinique\">éruption</span> ;<br>\n              <span class=\"kw-bio\">Hyperéosinophilie</span> sanguine\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":2},{"id":"114-4","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir reconnaître l’éruption du mégalérythème épidémique","contenu":"<table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Agent</strong></td>\n            <td><span class=\"kw-bio\">Parvovirus B19</span> — ubiquitaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Épidémies familiales / scolaires, enfants <strong><span class=\"kw-chiffre\">5-14 ans</span></strong> (âge scolaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Incubation</strong></td>\n            <td><strong>14 j</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Phase pré-éruptive</strong> (2 j, contagieuse)</td>\n            <td><span class=\"kw-clinique\">Fièvre</span> modérée, état général conservé, <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">myalgies</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Phase éruptive — forme typique</h4>\n      <ol>\n        <li><span class=\"kw-clinique\">Érythème + œdème des joues</span> = aspect <strong>« souffleté du visage »</strong> — 1ʳᵉ manifestation, s’atténue en quelques jours</li>\n        <li><span class=\"kw-clinique\">Éruption</span> à <strong>bords émiettés en « arabesques »</strong> ou en <strong>« guirlandes »</strong> du tronc et des faces internes des membres</li>\n        <li>Fluctuations sur <strong><span class=\"kw-chiffre\">1-3 semaines</span></strong></li>\n      </ol>\n\n      <h4>Autres formes</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Érythème</span> polymorphe</li>\n        <li><span class=\"kw-clinique\">Érythème</span> parfois <span class=\"kw-clinique\">purpurique en gants et en chaussettes</span></li>\n      </ul>\n\n      <p>Signes associés : <span class=\"kw-clinique\">arthralgies</span> fréquentes chez l’adulte jeune, <span class=\"kw-clinique\">fièvre</span> modérée.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Complications à connaître :</strong>\n        <ul>\n          <li><strong>Immunodéprimé</strong> : forme prolongée</li>\n          <li>Enfant atteint d’<strong>hémolyse chronique</strong> (drépanocytose, sphérocytose, thalassémie) → <span class=\"kw-alerte\">anémie aiguë érythroblastopénique</span></li>\n          <li><strong>Femme enceinte</strong> : <span class=\"kw-alerte\">anasarque fœtoplacentaire</span>, avortement précoce (1ᵉʳ trimestre), myocardite, anémie fœtale</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 167 — Hépatites virales</em></p>","frequence":0},{"id":"114-5","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir reconnaître le rash à l’ampicilline lors d’une infection à EBV","contenu":"<p>Au cours d’une <span class=\"kw-def\">mononucléose infectieuse (primo-infection EBV)</span>, l’administration d’<strong>ampicilline</strong> (ou moins fréquemment d’<span class=\"kw-ttt\">amoxicilline</span>) prescrite comme traitement de l’angine déclenche une <span class=\"kw-clinique\">éruption</span> caractéristique.</p>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sémio</strong></td>\n            <td><span class=\"kw-clinique\">Éruption morbilliforme maculo-papuleuse</span>, parfois associée à un <strong><span class=\"kw-clinique\">œdème</span> péri-orbitaire</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Délai d’apparition</strong></td>\n            <td>Survient classiquement <strong>après le 9ᵉ jour de prise</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Piège diagnostique</strong></td>\n            <td><span class=\"kw-alerte\">⚠️ Ne doit pas être confondue avec une allergie à la pénicilline</span> — il s’agit d’une <em>réaction immuno-<span class=\"kw-etio\">allergique</span> <span class=\"kw-etio\">virale</span>-médiée</em>, pas d’une <span class=\"kw-ci\">allergie</span> vraie</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 À retenir :</strong> devant une angine de l’adolescent / adulte jeune avec ampicilline → <span class=\"kw-clinique\">éruption</span> morbilliforme tardive = penser MNI <em>avant</em> d’étiqueter <span class=\"kw-etio\">allergique</span>. <span class=\"kw-bio\">Sérologies</span> <span class=\"kw-etio\">EBV</span> (IgM anti-VCA, MNI-test) + cytolyse hépatique, syndrome mononucléosique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0},{"id":"114-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications systémiques de l’érythrodermie","contenu":"<p>La gravité de l’érythrodermie est corrélée au <span class=\"kw-def\">terrain</span> sur lequel elle survient et aux complications qu’elle entraîne.</p>\n\n      <table class=\"matrix\">\n        <thead><tr><th>Type</th><th>Mécanisme / présentation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hydro-électrolytiques</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Déshydratation</span> par déperdition hydro-électrolytique ;<br>\n              <span class=\"kw-alerte\">Carence protéique</span> ; carences en oligo-éléments (<strong>fer, zinc, vitamines</strong>) ;<br>\n              Causes : vasodilatation cutanée, desquamation, suintement, <span class=\"kw-clinique\">œdème</span>, <span class=\"kw-clinique\">fièvre</span> ;<br>\n              <span class=\"kw-alerte\">Décompensation</span> cardiaque, respiratoire ou rénale possible\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Décubitus</strong></td>\n            <td>\n              Dénutrition, <span class=\"kw-clinique\">cachexie</span> ;<br>\n              Escarres ;<br>\n              <span class=\"kw-alerte\">TVP</span> → requiert une prise en charge rapide\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infections cutanées</strong></td>\n            <td>\n              Bactériennes : <strong><span class=\"kw-etio\">staphylocoque</span></strong> ;<br>\n              Virales : <strong>herpès</strong>, <strong>varicelle</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infections générales</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Urinaires</span> ++ ;<br>\n              <span class=\"kw-alerte\">Pneumopathie</span> ;<br>\n              <span class=\"kw-alerte\">Septicémie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thermorégulation</strong></td>\n            <td>Dysrégulation thermique importante : épisodes de <span class=\"kw-clinique\">fièvre</span> et d’<span class=\"kw-clinique\">hypothermie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hémodynamique</strong></td>\n            <td><span class=\"kw-alerte\">Troubles hémodynamiques</span> en cas de déperditions hydro-électrolytiques et protéiques majeures</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ <span class=\"kw-def\">Mortalité</span> jusqu’à<span class=\"kw-chiffre\"> 20 %</span></strong>, surtout liée à une <strong>complication infectieuse</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":0},{"id":"114-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une épidermolyse staphylococcique","contenu":"<p>Aussi appelée <em>scarlatine staphylococcique</em>. Diagnostic <strong>essentiellement clinique</strong>, à confirmer bactériologiquement.</p>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Agent</strong></td>\n            <td><span class=\"kw-bio\">Staphylococcus aureus</span> sécréteur d’<strong>entérotoxines</strong> (exfoliatines A et B ciblant la <strong>desmogléine 1</strong> → lyse des desmosomes → décollement cutané), ou <strong>TSST1</strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Enfants <strong>&lt;<span class=\"kw-chiffre\"> 5 ans</span></strong> (nouveaux-nés, nourrissons), jeune enfant, adulte immunodéprimé ou insuffisant rénal (mauvaise élimination des toxines)</td>\n          </tr>\n          <tr>\n            <td><strong>Contamination</strong></td>\n            <td>Contact avec un adulte porteur sain (épidémies en crèche)</td>\n          </tr>\n          <tr>\n            <td><strong>Incubation</strong></td>\n            <td><strong><span class=\"kw-chiffre\">48 h</span></strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Présentation clinique — points clés</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Pas d’angine ❌</span> et <strong>aucune autre atteinte muqueuse</strong> (distingue de la scarlatine SGA et du Kawasaki)</li>\n        <li>Contexte <span class=\"kw-etio\">infectieux</span> <strong>brutal</strong> : <span class=\"kw-clinique\">fièvre</span> + foyer initial à <em>S. aureus</em> (<span class=\"kw-clinique\">impétigo</span>, omphalite, otite externe…)</li>\n        <li><span class=\"kw-clinique\">Éruption</span> en 2 temps :\n          <ol>\n            <li><span class=\"kw-clinique\">Exanthème scarlatiniforme</span> débutant aux <strong>grands plis</strong> et aux <strong>régions péri-orificielles</strong> (ombilic ++)</li>\n            <li><span class=\"kw-clinique\">Évolution</span> vers un <span class=\"kw-alerte\">décollement bulleux superficiel</span> avec <strong>signe de Nikolsky</strong></li>\n          </ol>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Forme sévère — SSSS (Staphylococcal Scalded Skin Syndrome) :</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">éruption</span> maculaire diffuse → bulles à<span class=\"kw-chiffre\"> 24-48 h</span></li>\n          <li>Desquamation cutanée secondaire (3-5 j, voire 14-21 j)</li>\n          <li>Atteinte des phanères possible</li>\n          <li><span class=\"kw-alerte\">Hypotension</span></li>\n          <li>Atteinte multiviscérale (digestive, musculaire, rénale, hépatique, hématologique, neurologique)</li>\n        </ul>\n        En pratique : début par <span class=\"kw-clinique\">diarrhée</span> → <span class=\"kw-clinique\">hypotension</span> → <span class=\"kw-alerte\">choc</span>.\n      </div>\n\n      <h4>Confirmation diagnostique</h4>\n      <ul>\n        <li><strong>Prélèvements bactériologiques</strong> sur le foyer <span class=\"kw-etio\">infectieux</span> initial</li>\n        <li><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">ECBU</span>, ou <span class=\"kw-bio\">biopsie</span> selon contexte</li>\n      </ul>\n\n      <h4>Prise en charge</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong></li>\n        <li><span class=\"kw-ttt\">Antibiothérapie</span> : <span class=\"kw-ttt\">pénicilline M (oxacilline)</span> ; <span class=\"kw-ttt\">clindamycine</span> ou <span class=\"kw-ttt\">vancomycine</span> si SARM</li>\n        <li><span class=\"kw-ci\">Corticoïdes contre-indiqués ⚠️</span></li>\n        <li>Éviction scolaire jusqu’à <strong><span class=\"kw-chiffre\">48 h</span> de traitement</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"114-8","rang":"B","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques du syndrome de Kawasaki","contenu":"<p><span class=\"kw-def\">Syndrome adéno-cutanéo-muqueux fébrile</span> = <strong><span class=\"kw-def\">vascularite</span> aiguë multisystémique</strong> touchant les vaisseaux de <strong>moyen calibre</strong>. Pic d’<span class=\"kw-def\">incidence</span> à <strong><span class=\"kw-chiffre\">1 an</span></strong>, majorité &lt;<span class=\"kw-chiffre\"> 5 ans</span>, fréquence accrue dans les populations asiatiques (Japon ++).</p>\n\n      <h4><span class=\"kw-def\">Critères diagnostiques</span> (1 critère majeur constant + <span class=\"kw-chiffre\">≥ 4</span>/5 critères supplémentaires)</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Critère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Fièvre</span></strong><br><span class=\"kw-alerte\">(obligatoire)</span></td>\n            <td>Généralement <strong>élevée &gt;<span class=\"kw-chiffre\"> 38,5 °C</span></strong> ; non réduite par antipyrétiques ni ATB ; <strong>durée <span class=\"kw-chiffre\">≥ 5 jours</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Conjonctivite</strong></td>\n            <td><strong>Bilatérale</strong>, non exsudative, indolore (⚠️ sans <span class=\"kw-clinique\">œdème</span> des paupières)</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte buccopharyngée</strong></td>\n            <td>Chéilite, stomatite, pharyngite (⚠️ sans langue pseudomembraneuse)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\"><span class=\"kw-clinique\">Éruption</span> cutanée</span></strong></td>\n            <td>Maculopapuleuse diffuse sur tronc et membres, <span class=\"kw-clinique\">érythème</span> des paumes et plantes, <strong>desquamation précoce dès J5 au siège</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte des extrémités</strong></td>\n            <td><span class=\"kw-clinique\">Œdème</span> ferme et douloureux des mains et des pieds, desquamation <strong>tardive après J10</strong> (péri-unguéale)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Adénopathies</span> cervicales</strong></td>\n            <td><span class=\"kw-clinique\">Diamètre</span> <strong><span class=\"kw-chiffre\">≥ 1,5 cm</span></strong>, souvent <strong>unilatérales</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 Mnémo « ABCDEF »</strong>\n        <ul>\n          <li><strong>A</strong>dénopathie cervicale <span class=\"kw-chiffre\">≥ 1,5 cm</span></li>\n          <li><strong>B</strong>ouche : chéilite, stomatite, pharyngite</li>\n          <li><strong>C</strong>onjonctivite bilatérale non exsudative</li>\n          <li><strong>D</strong>esquamation + <span class=\"kw-clinique\">œdème</span> des extrémités</li>\n          <li><strong>E</strong>xanthème maculo-papuleux</li>\n          <li><strong>F</strong>ièvre élevée <span class=\"kw-chiffre\">≥ 5 jours</span> <strong>(obligatoire)</strong></li>\n        </ul>\n      </div>\n\n      <h4>Différencier Scarlatine <span class=\"kw-bio\">vs</span> Kawasaki</h4>\n      <table class=\"matrix\">\n        <thead><tr><th></th><th>Scarlatine</th><th>Kawasaki</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Début desquamation</strong></td><td><span class=\"kw-chiffre\">J0</span></td><td>J5</td></tr>\n          <tr><td><strong>Localisation initiale</strong></td><td>Extrémités</td><td><strong>Siège</strong></td></tr>\n          <tr><td><strong>Localisation tardive</strong></td><td>—</td><td>Extrémités vers J10</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signes évocateurs supplémentaires</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Hyperirritabilité</span>, enfant difficilement examinable (signe quasi-constant)</li>\n        <li><strong>Réactivation (induration) de la cicatrice de BCG</strong> chez le nourrisson</li>\n        <li>Atteintes possibles : <span class=\"kw-clinique\">arthralgies</span>/arthrites, uvéite-rétinite, <span class=\"kw-clinique\">vomissements</span>/<span class=\"kw-clinique\">douleurs abdominales</span>, <strong><span class=\"kw-def\">hépatite</span> cytolytique</strong>, hydrocholécyste ⭐ (caractéristique), <span class=\"kw-def\">méningite</span> lymphocytaire</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Complications cardiovasculaires</strong> (font la gravité de la maladie) :\n        <ol>\n          <li>Initialement : <span class=\"kw-alerte\">myocardite</span>, <span class=\"kw-alerte\">péricardite</span></li>\n          <li>Secondairement : <span class=\"kw-alerte\">dilatations voire anévrismes des coronaires</span> ⭐</li>\n          <li>Tardives : troubles du rythme, <span class=\"kw-clinique\">infarctus</span></li>\n        </ol>\n      </div>\n\n      <h4>Paraclinique</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Syndrome inflammatoire</span> : <span class=\"kw-bio\">CRP</span> ↑, <span class=\"kw-bio\">VS</span> ↑ (quasi-constant)</li>\n        <li><span class=\"kw-bio\">NFS</span> : hyperleucocytose à PNN, anémie <span class=\"kw-etio\">inflammatoire</span>, <strong>thrombocytose tardive</strong></li>\n        <li><span class=\"kw-bio\">BU : leucocyturie amicrobienne</span> quasi-constante, évocatrice</li>\n        <li><strong><span class=\"kw-imagerie\">ETT</span> systématique</strong> : dilatation sans perte de parallélisme des bords coronaires, irrégularité de la lumière, hyperéchogénicité des parois</li>\n      </ul>\n\n      <h4>Prise en charge</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> indispensable en phase aiguë</li>\n        <li><span class=\"kw-ttt\">Ig polyvalentes IV</span> : stop inflammation + prévention coronarienne</li>\n        <li><span class=\"kw-ttt\">Aspirine</span> : dose anti-<span class=\"kw-etio\">inflammatoire</span> en phase aiguë, puis anti-agrégante (<span class=\"kw-chiffre\">≥ 6-8 semaines</span>, ou plus si lésions coronariennes)</li>\n        <li><span class=\"kw-def\">Surveillance</span> échocardiographique +++</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/114/kawasaki-1.png\" alt=\"Planche clinique du syndrome de Kawasaki : conjonctivite bilatérale, chéilite et langue framboisée, érythème palmo-plantaire, œdème et desquamation péri-unguéale des extrémités, exanthème du tronc, adénopathie cervicale\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Syndrome de Kawasaki</span> — planche clinique des signes diagnostiques : conjonctivite bilatérale non exsudative, chéilite et langue framboisée, <span class=\"kw-clinique\">érythème</span> palmo-plantaire, <span class=\"kw-clinique\">œdème</span> des extrémités avec desquamation péri-unguéale, exanthème maculo-papuleux et <span class=\"kw-clinique\">adénopathie</span> cervicale.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/114/kawasaki-2.png\" alt=\"Montage des principaux signes et symptômes du syndrome de Kawasaki\" loading=\"lazy\">\n        <figcaption>Principaux signes du syndrome de Kawasaki — conjonctivite non exsudative, énanthème buccal et langue framboisée, exanthème, hyperirritabilité, <span class=\"kw-clinique\">œdème</span> et desquamation des extrémités, <span class=\"kw-clinique\">adénopathie</span> cervicale. <em>(Planche illustrative à légendes d’origine en anglais.)</em></figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/114/kawasaki-3.png\" alt=\"Schéma de synthèse du syndrome de Kawasaki : topographie des signes cliniques et complication coronarienne\" loading=\"lazy\">\n        <figcaption>Schéma de synthèse — topographie des signes (<span class=\"kw-clinique\">adénopathie</span> cervicale, yeux rouges, lèvres fissurées et langue framboisée, mains et pieds œdématiés, exanthème du tronc) et <span class=\"kw-alerte\">complication coronarienne</span> (anévrismes). <em>(Infographie à légendes d’origine en anglais.)</em></figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":0},{"id":"114-9","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir que l’érythrodermie est une urgence et savoir la prendre en charge","contenu":"<div class=\"callout callout-danger\">\n        <strong>🔥 L’érythrodermie est une <span class=\"kw-alerte\">urgence</span> dermatologique.</strong> <span class=\"kw-def\">Mortalité</span> jusqu’à <strong><span class=\"kw-chiffre\">20 %</span></strong>. <span class=\"kw-alerte\">Hospitalisation</span> systématique en urgence pour PEC thérapeutique <em>et</em> étiologique immédiate.\n      </div>\n\n      <h4>1. Reconnaître l’érythrodermie</h4>\n      <ul>\n        <li><span class=\"kw-def\">Érythème confluant + desquamation &gt; 90 % SC, &gt; 6 semaines</span></li>\n        <li><span class=\"kw-clinique\">Prurit</span> constant, pachydermie (épaississement plis), atteinte muqueuse (énanthème, chéilite, conjonctivite)</li>\n        <li>Phanères (après quelques semaines) : chute cheveux/sourcils/cils, ongles dystrophiques, <strong>ligne de Beau</strong>, chute possible de l’ongle</li>\n        <li><span class=\"kw-clinique\">Polyadénopathie</span> généralisée souvent associée</li>\n        <li><span class=\"kw-clinique\">Œdème du visage</span> avec possible <strong>ectropion</strong></li>\n      </ul>\n\n      <h4>2. Mesures générales (en <span class=\"kw-alerte\">urgence</span>)</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> ++</strong></li>\n        <li>Bilan <span class=\"kw-ttt\">biologique</span> pour évaluer la gravité de la dermatose</li>\n        <li><span class=\"kw-ttt\">Rééquilibration hydro-électrolytique</span> (réchauffement, apports IV)</li>\n        <li>Traitement des éventuelles défaillances viscérales (cardiaque, respiratoire, rénale)</li>\n      </ul>\n\n      <h4>3. Traitement symptomatique</h4>\n      <ul>\n        <li><strong>Réchauffer le malade</strong> : pour limiter les pertes cataboliques, l’hypercatabolisme et la dénutrition</li>\n        <li>Formes graves : <span class=\"kw-ttt\">corticothérapie locale de niveau 1</span> (très forte) → amélioration rapide des symptômes</li>\n      </ul>\n\n      <h4>4. Démarche étiologique en parallèle</h4>\n      <ul>\n        <li>Ancienneté de l’<span class=\"kw-clinique\">éruption</span>, ATCD dermatologiques et autres</li>\n        <li><strong>Prise médicamenteuse</strong> (<span class=\"kw-alerte\">DRESS</span>, toxidermie) → arrêt du médicament suspect</li>\n        <li>Traitements topiques utilisés</li>\n        <li>Contexte <span class=\"kw-etio\">infectieux</span></li>\n        <li><strong><span class=\"kw-bio\">Biopsie</span> cutanée</strong> : peut mettre en évidence des signes histologiques spécifiques (à <em>répéter</em> en cas de suspicion de lymphome cutané)</li>\n        <li>Prélèvements bactériologiques et parasitologiques selon contexte</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 117 — <span class=\"kw-clinique\">Psoriasis</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0},{"id":"114-10","rang":"A","rubrique":"Étiologies","titre":"Connaître la principale cause d’exanthème chez l’enfant et chez l’adulte","contenu":"<table class=\"matrix\">\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Principale cause</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td><span class=\"kw-clinique\">Causes virales</span> (rougeole, exanthème subit, mégalérythème, rubéole, entérovirus…) <em>et</em> <span class=\"kw-clinique\">toxidermies maculo-papuleuses</span></td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td><span class=\"kw-clinique\">Toxidermies médicamenteuses</span> (cause fréquente) ; <span class=\"kw-clinique\">IST</span> à évoquer systématiquement (syphilis, primo-infection <span class=\"kw-etio\">VIH</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 À retenir :</strong> chez l’enfant la cause est <strong><span class=\"kw-etio\">virale</span></strong> dans la grande majorité des cas ; chez l’adulte, il faut toujours évoquer <strong>toxidermie</strong> + <strong>IST</strong> (<span class=\"kw-etio\">VIH</span>, syphilis) devant un exanthème.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 162 — IST · 169 — <span class=\"kw-etio\">VIH</span> · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0},{"id":"114-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les trois causes d’exanthème à évoquer systématiquement chez l’adulte","contenu":"<p>Trois causes à évoquer <strong>systématiquement</strong> face à un exanthème de l’adulte :</p>\n\n      <table class=\"matrix\">\n        <thead><tr><th>Cause</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Toxidermie médicamenteuse</strong></td>\n            <td>\n              Introduction d’un médicament <strong><span class=\"kw-chiffre\">5-14 jours</span></strong> avant ;<br>\n              <span class=\"kw-clinique\">Prurit</span>, polymorphisme, <span class=\"kw-bio\">hyperéosinophilie</span> ;<br>\n              Spectre : exanthème maculo-papuleux → <strong><span class=\"kw-alerte\">DRESS</span></strong> → <span class=\"kw-alerte\">Stevens-Johnson</span> / Lyell\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Primo-infection <span class=\"kw-etio\">VIH</span></strong></td>\n            <td>\n              Syndrome pseudo-grippal fébrile + exanthème <span class=\"kw-clinique\">morbilliforme</span> ou <span class=\"kw-clinique\">roséoliforme</span> ;<br>\n              <span class=\"kw-bio\">Sérologie VIH + PCR ARN VIH</span> (charge <span class=\"kw-etio\">virale</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Syphilis secondaire</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Roséole syphilitique</span> (1ʳᵉ <span class=\"kw-clinique\">éruption</span> de la syphilis secondaire) ;<br>\n              Pas de <span class=\"kw-clinique\">prurit</span>, plantes / paumes possibles ;<br>\n              <span class=\"kw-bio\">TPHA / VDRL</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 Bilan paraclinique standard chez l’adulte</strong> (en l’absence de cause évidente) : <span class=\"kw-bio\">NFS</span>, tests hépatiques, <strong><span class=\"kw-bio\">sérologies</span> MNI, TPHA/VDRL, <span class=\"kw-etio\">VIH</span> (+ <span class=\"kw-bio\">PCR</span> VIH)</strong>. Distracteur classique : <span class=\"kw-ci\">PAS de CRP ❌</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 169 — <span class=\"kw-etio\">VIH</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":1},{"id":"114-12","rang":"B","rubrique":"Étiologies","titre":"Connaître les quatre causes principales d’exanthème roséoliforme","contenu":"<table class=\"matrix\">\n        <thead><tr><th>Famille</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Virus</strong></td>\n            <td>\n              <strong>Exanthème subit (HHV6/7)</strong> = roséole infantile ;<br>\n              <strong>Rubéole</strong> ;<br>\n              <strong>Primo-infection <span class=\"kw-etio\">VIH</span></strong> ;<br>\n              <em>Virus West-Nile (mention)</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bactéries</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Fièvre</span> typhoïde</strong> (1/3 des cas à la phase d’état) ;<br>\n              <strong>Roséole syphilitique</strong> (1ʳᵉ <span class=\"kw-clinique\">éruption</span> de la syphilis secondaire)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>Maladie de Still</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 « 4 causes principales » à retenir (pédagogique) :</strong>\n        <ol>\n          <li>Exanthème subit (HHV6/7) — chez le nourrisson</li>\n          <li>Rubéole</li>\n          <li>Primo-infection <span class=\"kw-etio\">VIH</span> — chez l’adulte</li>\n          <li>Syphilis secondaire (roséole syphilitique) — chez l’adulte</li>\n        </ol>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"114-13","rang":"B","rubrique":"Étiologies","titre":"Connaître les trois causes principales d’exanthème morbilliforme","contenu":"<table class=\"matrix\">\n        <thead><tr><th>Famille</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Virus</strong></td>\n            <td>\n              <strong>Rougeole</strong> (cause éponyme) ;<br>\n              <strong>Mégalérythème épidémique</strong> (Parvovirus B19) ;<br>\n              <strong>Mononucléose infectieuse</strong> (<span class=\"kw-etio\">EBV</span>) — avec <span class=\"kw-clinique\">rash</span> à l’ampicilline ;<br>\n              <em>Aussi : primo-<span class=\"kw-etio\">VIH</span>, <span class=\"kw-def\">hépatite</span> B, dengue, entérovirus, adénovirus</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bactéries</strong></td>\n            <td><span class=\"kw-etio\">Méningocoque</span>, leptospirose, rickettsioses, mycoplasme</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>Toxoplasmose, Kawasaki, <strong>toxidermies maculo-papuleuses</strong> (fréquentes chez l’enfant et l’adulte)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 « 3 causes principales » à retenir (pédagogique) :</strong>\n        <ol>\n          <li>Rougeole</li>\n          <li>Mégalérythème épidémique (Parvovirus B19)</li>\n          <li>Mononucléose infectieuse (<span class=\"kw-etio\">EBV</span>)</li>\n        </ol>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — déclaration obligatoire / méningococcémie (cf. item 151 — Méningites)</em></p>","frequence":0},{"id":"114-14","rang":"B","rubrique":"Étiologies","titre":"Connaître les deux causes principales d’exanthème scarlatiniforme","contenu":"<table class=\"matrix\">\n        <thead><tr><th>Cause</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Scarlatine</strong><br>(SGA, Streptococcus pyogenes)</td>\n            <td>\n              <span class=\"kw-bio\">Toxine érythrogène (exotoxine)</span> ;<br>\n              Enfant <span class=\"kw-chiffre\">5-10 ans</span> ;<br>\n              Angine + glossite → langue framboisée → exanthème scarlatiniforme aux <strong>grands plis</strong> ;<br>\n              <strong>TDR <span class=\"kw-etio\">streptocoque</span> A</strong> systématique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Épidermolyse staphylococcique</strong><br>(scarlatine staphylococcique)</td>\n            <td>\n              <span class=\"kw-bio\">S. aureus</span> sécréteur d’<strong>exfoliatines</strong> ou TSST1 ;<br>\n              <span class=\"kw-clinique\">Pas d’angine ❌</span> et <strong>pas d’atteinte muqueuse</strong> ;<br>\n              Exanthème scarlatiniforme aux <strong>grands plis</strong> et <strong>péri-orificiel</strong> → décollement bulleux superficiel (Nikolsky)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 Distinction clé :</strong> la <strong>scarlatine SGA</strong> a une <strong>angine</strong> et une <strong>glossite</strong> ; l’<strong>épidermolyse staphylococcique</strong> n’a <strong>ni angine ni atteinte muqueuse</strong>, et évolue vers un décollement bulleux (Nikolsky +).\n      </div>\n\n      <p>Cause additionnelle (à connaître hors « 2 principales ») : <strong>Maladie de Kawasaki</strong> peut prendre une présentation scarlatiniforme.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"114-15","rang":"B","rubrique":"Étiologies","titre":"Connaître les quatre principaux exanthèmes à risque chez la femme enceinte","contenu":"<p>Quatre causes d’exanthème de la femme enceinte associées à un <span class=\"kw-alerte\">risque fœtal</span> ⚠️ :</p>\n\n      <table class=\"matrix\">\n        <thead><tr><th>Cause</th><th>Risque fœtal</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Rubéole</strong><br>(non immunisée)</td>\n            <td>\n              <span class=\"kw-alerte\">Embryofœtopathie sévère</span> si infection &lt; 18 SA :<br>\n              RCIU, fausse couche ;<br>\n              Surdité, microcéphalie, retard psychomoteur ;<br>\n              Malformations cardiaques (PCA, CIV, sténose AP) ;<br>\n              Microphtalmie, cataracte, rétinopathie pigmentaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toxoplasmose</strong><br>(non immunisée)</td>\n            <td><span class=\"kw-alerte\">Toxoplasmose congénitale</span> (atteinte neurologique et oculaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Parvovirus B19</strong><br>(non immunisée)</td>\n            <td>\n              <span class=\"kw-alerte\">Anasarque fœtoplacentaire</span> (si infection au 2ᵉ trimestre) ;<br>\n              Anémie fœtale, myocardite, avortement précoce\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Syphilis</strong></td>\n            <td><span class=\"kw-alerte\">Syphilis congénitale</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>📌 Bilan systématique devant un exanthème chez la femme enceinte</strong> (en tenant compte du statut sérologique de début de <span class=\"kw-ci\">grossesse</span>) : <span class=\"kw-bio\">sérologies</span> <strong>toxoplasmose, rubéole, <span class=\"kw-etio\">CMV</span>, parvovirus B19, syphilis</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"114-16","rang":"A","rubrique":"Étiologies","titre":"Savoir évoquer une rougeole chez l’enfant et chez l’adulte","contenu":"<table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Agent</strong></td>\n            <td><span class=\"kw-bio\">Morbillivirus</span> (paramyxovirus, ARN)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Enfants et adultes <strong>non vaccinés</strong> (vaccination incomplète, ATCD absent). Nourrissons protégés jusqu’à <strong><span class=\"kw-chiffre\">6 mois</span></strong> par AC maternels</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span> à risque</strong></td>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 1 an</span></strong>, adulte (notamment &gt;<span class=\"kw-chiffre\"> 20 ans</span>), <strong>femme enceinte</strong>, <strong>immunodéprimé</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Transmission</strong></td>\n            <td>Directe par voie <strong>aérienne</strong>, transmission placentaire</td>\n          </tr>\n          <tr>\n            <td><strong>Incubation</strong></td>\n            <td><strong><span class=\"kw-chiffre\">10-12 jours</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Contagiosité</strong> ⭐</td>\n            <td><strong><span class=\"kw-chiffre\">5 jours</span> avant</strong> l’<span class=\"kw-clinique\">éruption</span> jusqu’au <strong>5ᵉ jour après</strong> le début de l’<span class=\"kw-clinique\">éruption</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Phase d’invasion (catarrhale / pré-éruptive, 2-4 j)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre élevée 39-40 °C</span></li>\n        <li><span class=\"kw-clinique\">Catarrhe oculo-respiratoire</span> : larmoiement, conjonctivite, rhinorrhée, <span class=\"kw-clinique\">toux</span></li>\n        <li><strong>Signe de Köplik</strong> ⭐ (pathognomonique) : <span class=\"kw-clinique\">taches punctiformes blanc-bleuté</span> sur muqueuse jugale <span class=\"kw-etio\">inflammatoire</span> (semis de papules à la face interne des joues) — survient en <em>fin</em> de période catarrhale</li>\n      </ul>\n\n      <h4>Phase éruptive (~<span class=\"kw-chiffre\">2 semaines</span> après contage)</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> décroissante à la généralisation de l’<span class=\"kw-clinique\">éruption</span></li>\n        <li>Persistance des signes catarrhaux</li>\n        <li><span class=\"kw-clinique\">Exanthème morbilliforme</span> non prurigineux respectant des <strong>intervalles de peau saine</strong> :\n          <ol>\n            <li>Débute en <strong>rétro-auriculaire</strong></li>\n            <li>Extension descendante vers le visage et le reste du corps, en <strong>1 seule poussée sur <span class=\"kw-chiffre\">24-48 h</span></strong></li>\n            <li>Régression en <strong><span class=\"kw-chiffre\">5-6 jours</span></strong></li>\n          </ol>\n        </li>\n      </ul>\n\n      <h4>Complications ⚠️</h4>\n      <ul>\n        <li><strong>Infectieuses</strong> (réascension thermique) : bronchite, pneumopathie, surinfection pulmonaire, OMA purulente</li>\n        <li><strong>Neurologiques</strong> :\n          <ul>\n            <li><span class=\"kw-alerte\">Encéphalite aiguë morbilleuse</span> post-éruptive (1/1000)</li>\n            <li><span class=\"kw-alerte\">Panencéphalite sclérosante subaiguë de Van Bogaert (PESS)</span> retardée <span class=\"kw-chiffre\">5-10 ans</span> (1/100 000, 1/6 000 si rougeole &lt;<span class=\"kw-chiffre\"> 1 an</span>)</li>\n          </ul>\n        </li>\n        <li>Autres : <span class=\"kw-def\">hépatite</span>, pancréatite, kératite, cécité</li>\n      </ul>\n\n      <h4>Confirmation <span class=\"kw-ttt\">biologique</span> <strong>systématique</strong> (déclaration obligatoire)</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Méthode</th><th>Prélèvement</th><th>Période optimale</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">PCR</span> (directe)</strong></td><td>Salive, nez, gorge ou sang, voire urine</td><td><strong><span class=\"kw-chiffre\">J0</span>-J5</strong> (jusqu’à J+12)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Sérologie</span> IgM (indirecte)</strong></td><td>Salive ou sérum</td><td><strong><span class=\"kw-chiffre\">J3</span>-J28</strong> (jusqu’à J60)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prise en charge</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Hospitalisation</span> seulement si <span class=\"kw-alerte\">signes de gravité</span></li>\n        <li>Traitement symptomatique : <span class=\"kw-ttt\">paracétamol</span></li>\n        <li>ATB probabiliste réservée aux <strong>surinfections bactériennes</strong> (<span class=\"kw-ttt\">amoxicilline-acide clavulanique</span> : <span class=\"kw-etio\">pneumocoque</span>, S. aureus)</li>\n        <li><strong>Déclaration obligatoire à l’ARS</strong> sans délai</li>\n        <li><strong>Éviction de collectivité</strong> jusqu’à <strong><span class=\"kw-chiffre\">5 jours</span> après</strong> le début de l’<span class=\"kw-clinique\">éruption</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 Mesures préventives chez sujet contact (rappel)</strong>\n        <ul>\n          <li>Nourrisson &lt;<span class=\"kw-chiffre\"> 6 mois</span>, mère non immunisée → <strong>Ig polyclonales IV</strong> (efficaces dans les <span class=\"kw-chiffre\">6 jours</span>)</li>\n          <li>Nourrisson <span class=\"kw-chiffre\">6-11 mois</span>, contact &lt;<span class=\"kw-chiffre\"> 72 h</span> → <strong>1 dose ROR</strong> (+ 2 doses au calendrier)</li>\n          <li><span class=\"kw-chiffre\">≥ 1 an</span> né depuis 1980 non vacciné → <strong>2 doses ROR</strong> à<span class=\"kw-chiffre\"> 1 mois</span> d’intervalle</li>\n          <li>Immunodéprimé / femme enceinte non immunisée → <strong>Ig polyclonales IV</strong></li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 165 — Oreillons · 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"114-17","rang":"A","rubrique":"Étiologies","titre":"Connaître trois causes d’érythrodermie chez l’adulte","contenu":"<table class=\"matrix\">\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Dermatoses inflammatoires</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Psoriasis</span> (+++)</strong> ;<br>\n              <strong><span class=\"kw-clinique\">Eczéma</span> / Dermatite <span class=\"kw-etio\">atopique</span> (+++)</strong> ;<br>\n              <strong>Toxidermies — <span class=\"kw-alerte\">DRESS</span> (+++)</strong> ;<br>\n              Lichen plan\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémopathies</strong></td>\n            <td><strong>Lymphome T cutané épidermotrope = <span class=\"kw-clinique\">syndrome de Sézary</span> (+++)</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Infections</strong></td>\n            <td>\n              <strong><span class=\"kw-etio\">VIH</span> (+)</strong> ;<br>\n              <strong><span class=\"kw-etio\">Gale</span> croûteuse (++)</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Idiopathique</strong></td>\n            <td><span class=\"kw-chiffre\">10-15 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>📌 « 3 causes principales » à retenir :</strong>\n        <ol>\n          <li><strong><span class=\"kw-clinique\">Psoriasis</span></strong> érythrodermique</li>\n          <li><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-etio\">atopique</span> / <span class=\"kw-clinique\">eczéma</span></strong> érythrodermique</li>\n          <li><strong>Toxidermies — <span class=\"kw-alerte\">DRESS</span></strong> (médicamenteuse)</li>\n        </ol>\n        À évoquer aussi : <strong><span class=\"kw-clinique\">syndrome de Sézary</span></strong> (lymphome T cutané) → <span class=\"kw-bio\">biopsie</span> cutanée à répéter si suspicion.\n      </div>\n\n      <h4>Chez l’enfant (à part)</h4>\n      <ul>\n        <li><strong>Nouveau-né / &lt;<span class=\"kw-chiffre\"> 3 mois</span></strong> : érythrodermie ichtyosiforme, maladie de Leiner-Moussous (<span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span>), déficits immunitaires congénitaux</li>\n        <li><strong>&gt;<span class=\"kw-chiffre\"> 3 mois</span></strong> : <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-etio\">atopique</span> (+++), histiocytose langerhansienne</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 117 — <span class=\"kw-clinique\">Psoriasis</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 169 — <span class=\"kw-etio\">VIH</span> · 320 — Myélome multiple des os · 326 — Cadre réglementaire de la prescription et reco pour bon usage</em></p>","frequence":0},{"id":"114-18","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’une langue framboisée","contenu":"<p>La <span class=\"kw-def\">langue framboisée</span> est une glossite caractéristique de la <strong>scarlatine</strong> (et également un critère évocateur du <span class=\"kw-clinique\">syndrome de Kawasaki</span>).</p>\n\n      <h4><span class=\"kw-clinique\">Évolution</span> séméiologique de la glossite scarlatineuse</h4>\n      <ol>\n        <li>Langue d’abord <span class=\"kw-clinique\">saburrale</span> (enduit blanc épais)</li>\n        <li><strong>Dépapillation progressive</strong> de la périphérie vers le centre, réalisant un aspect en <strong>« V lingual »</strong></li>\n        <li>Aspect <strong>rugueux à J6</strong> = <span class=\"kw-clinique\">langue framboisée</span> (glossite <strong>exfoliatrice</strong>) : rouge vif, papilles saillantes, aspect en grain de fraise</li>\n        <li>Régression en <strong><span class=\"kw-chiffre\">1 semaine</span></strong></li>\n      </ol>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie de langue framboisée n’est présente dans les fiches sources du dossier <code>fiches sources/114/</code>. Kevin fournira l’image (Pilly, Collège ou recherche web ciblée) à déposer dans <code>assets/images/114/langue-framboisee.{ext}</code>.\n      </div>\n      <!-- TODO Kevin : déposer langue-framboisee.{ext} dans assets/images/114/ -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"114-19","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un exanthème morbilliforme","contenu":"<p>L’<span class=\"kw-def\">exanthème morbilliforme</span> (forme « rougeoleuse ») est une <span class=\"kw-clinique\">éruption</span> <strong>maculo-papuleuse</strong> rouge, à <strong>léger relief</strong>, avec des plaques pouvant <strong>confluer</strong> séparées par des <strong>intervalles de peau saine</strong>.</p>\n\n      <h4>Sémiologie attendue à la photographie</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Maculo-papuleux</span> rouge</li>\n        <li>Léger relief palpable</li>\n        <li>Plaques pouvant <strong>confluer</strong> en placards plus larges</li>\n        <li>Intervalles de peau saine préservés</li>\n        <li><span class=\"kw-clinique\">Évolution</span> descendante (rétro-auriculaire → visage → tronc → membres) en cas de rougeole typique</li>\n      </ul>\n\n      <h4>Diagnostics étiologiques à connaître devant une photo morbilliforme</h4>\n      <ul>\n        <li><strong>Rougeole</strong> (paramyxovirus) — recherche d’un signe de Köplik associé</li>\n        <li><strong>Mégalérythème épidémique</strong> (Parvovirus B19) — joues souffletées</li>\n        <li><strong>MNI</strong> (<span class=\"kw-etio\">EBV</span>) — <span class=\"kw-clinique\">rash</span> à l’ampicilline</li>\n        <li><strong>Toxidermie maculo-papuleuse</strong></li>\n        <li><strong>Primo-infection <span class=\"kw-etio\">VIH</span></strong></li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/114/rougeole-chronologie-infection.png\" alt=\"Chronologie clinique et biologique de la rougeole — phase d'invasion, signe de Köplik, phase éruptive descendante\" loading=\"lazy\">\n        <figcaption>Chronologie de l’infection rougeoleuse (phase d’invasion catarrhale → signe de Köplik → exanthème morbilliforme descendant rétro-auriculaire). Source : fiche source EDN item 114, Collège de Dermatologie.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter (photographie clinique).</strong> La fiche source ne contient pas de cliché purement « morbilliforme cutané » prêt à l’emploi. Kevin pourra déposer une photo clinique (Pilly / Collège) dans <code>assets/images/114/exantheme-morbilliforme.{ext}</code> pour compléter la légende ci-dessus.\n      </div>\n      <!-- TODO Kevin : déposer exantheme-morbilliforme.{ext} dans assets/images/114/ -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 167 — Hépatites virales</em></p>","frequence":1},{"id":"114-20","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’un exanthème scarlatiniforme","contenu":"<p>L’<span class=\"kw-def\">exanthème scarlatiniforme</span> se présente sous forme de <strong>vastes nappes rouge vif</strong> uniformes et congestives, sans intervalle de peau saine, à la <strong>palpation granitée</strong>.</p>\n\n      <h4>Sémiologie attendue à la photographie</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Plaques / nappes diffuses</span></li>\n        <li>Rouge vif ou sombre, <strong>congestif</strong></li>\n        <li><strong>Pas d’intervalle de peau saine</strong> (différencie du morbilliforme)</li>\n        <li>Palpation <strong>granitée</strong></li>\n        <li>Topographie : prédominance aux <strong>grands plis</strong>, extension à la partie inférieure de l’abdomen, extrémités (respect des paumes et plantes), visage (respect péri-buccal)</li>\n        <li><span class=\"kw-clinique\">Évolution</span> vers une <strong>desquamation post-éruptive « en doigt de gant »</strong> des extrémités à J6</li>\n      </ul>\n\n      <h4>Étiologies à évoquer devant une photo scarlatiniforme</h4>\n      <ul>\n        <li><strong>Scarlatine</strong> (SGA, toxine érythrogène) — avec angine + glossite</li>\n        <li><strong>Épidermolyse staphylococcique</strong> — sans angine, signe de Nikolsky</li>\n        <li><strong>Maladie de Kawasaki</strong> (forme scarlatiniforme possible)</li>\n        <li>Toxidermie médicamenteuse</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie d’exanthème scarlatiniforme n’est présente dans les fiches sources du dossier <code>fiches sources/114/</code>. Kevin fournira l’image à déposer dans <code>assets/images/114/exantheme-scarlatiniforme.{ext}</code>.\n      </div>\n      <!-- TODO Kevin : déposer exantheme-scarlatiniforme.{ext} dans assets/images/114/ -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"114-21","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une érythrodermie","contenu":"<p>L’<span class=\"kw-def\">érythrodermie</span> est un <span class=\"kw-clinique\">érythème</span> confluant + desquamation touchant <strong>&gt;<span class=\"kw-chiffre\"> 90 %</span> de la surface corporelle</strong>, d’<span class=\"kw-clinique\">évolution</span> prolongée <strong>&gt;<span class=\"kw-chiffre\"> 6 semaines</span></strong>.</p>\n\n      <h4>Sémiologie attendue à la photographie</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Érythème</span> <strong>généralisé</strong>, <span class=\"kw-etio\">inflammatoire</span>, plus violacé aux zones déclives</li>\n        <li><span class=\"kw-clinique\">Desquamation constante</span> : fine ou en larges lambeaux</li>\n        <li><strong>Pachydermie</strong> (épaississement) prédominant aux plis</li>\n        <li><span class=\"kw-clinique\">Œdème du visage</span> avec possible <strong>ectropion</strong> (éversion de la muqueuse)</li>\n        <li>Atteinte des phanères après quelques semaines : chute de cheveux, sourcils, cils ; ongles dystrophiques, <strong>ligne de Beau</strong> ; possible chute de l’ongle</li>\n        <li>Atteinte muqueuse : chéilite, conjonctivite, stomatite</li>\n        <li><span class=\"kw-clinique\">Polyadénopathie</span> souvent associée (grande taille, souples, mobiles)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Aucune photographie d’érythrodermie n’est présente dans les fiches sources du dossier <code>fiches sources/114/</code>. Kevin fournira l’image (Pilly, Collège ou recherche ciblée) à déposer dans <code>assets/images/114/erythrodermie.{ext}</code>.\n      </div>\n      <!-- TODO Kevin : déposer erythrodermie.{ext} dans assets/images/114/ -->\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 117 — <span class=\"kw-clinique\">Psoriasis</span> · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 169 — <span class=\"kw-etio\">VIH</span> · 320 — Myélome multiple des os</em></p>","frequence":0},{"id":"114-22","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un mégalérythème","contenu":"<p>Le <span class=\"kw-def\">mégalérythème épidémique</span> (Parvovirus B19) a une présentation très typique en 2 temps.</p>\n\n      <h4>Sémiologie attendue à la photographie</h4>\n      <ol>\n        <li><span class=\"kw-clinique\">Érythème + œdème des joues</span> = aspect <strong>« souffleté du visage »</strong> — 1ʳᵉ manifestation, s’atténue en quelques jours</li>\n        <li><span class=\"kw-clinique\">Éruption</span> secondaire à <strong>bords émiettés en « arabesques »</strong> ou en <strong>« guirlandes »</strong> du tronc et des faces internes des membres</li>\n      </ol>\n\n      <h4>Autres formes</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Érythème</span> polymorphe</li>\n        <li><span class=\"kw-clinique\">Érythème</span> parfois <strong>purpurique en gants et en chaussettes</strong></li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/114/megalerytheme-joues-souffletees.png\" alt=\"Mégalérythème épidémique : aspect souffleté du visage avec érythème et œdème des joues\" loading=\"lazy\">\n        <figcaption>Mégalérythème épidémique (Parvovirus B19) — aspect « souffleté du visage » avec érythème et <span class=\"kw-clinique\">œdème</span> des joues, première manifestation chez l’enfant d’âge scolaire. Source : fiche source EDN item 114, Collège de Dermatologie.</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 167 — Hépatites virales</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> absolue :</strong> l'<span class=\"kw-alerte\">érythrodermie</span> est une <span class=\"kw-alerte\">urgence dermatologique</span> imposant une <span class=\"kw-ttt\">prise en charge thérapeutique et étiologique immédiate</span>.<br><strong>Définition piège :</strong> <span class=\"kw-clinique\">érythème</span> confluant + <span class=\"kw-clinique\">desquamation</span> sur <span class=\"kw-chiffre\">> 90 % de la surface corporelle</span>, évoluant depuis <span class=\"kw-chiffre\">≥ 6 semaines</span>.<br><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-alerte\">mortalité</span> jusqu'à <span class=\"kw-chiffre\">20 %</span>, surtout par complication infectieuse.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">hospitalisation en urgence</span>, <span class=\"kw-bio\">bilan biologique</span> de gravité et <span class=\"kw-ttt\">rééquilibration hydro-électrolytique</span>.<br><strong>Autres urgences :</strong> évoquer un <span class=\"kw-etio\">syndrome de Kawasaki</span> et une <span class=\"kw-etio\">épidermolyse staphylococcique</span> / <span class=\"kw-alerte\">choc toxique</span> devant un exanthème fébrile.</p>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> en <span class=\"kw-alerte\">urgence</span> :</strong> toute <span class=\"kw-alerte\">érythrodermie</span> (PEC symptomatique et étiologique immédiate).<br><strong>Hospitalisation indispensable :</strong> <span class=\"kw-etio\">maladie de Kawasaki</span> en phase aiguë (<span class=\"kw-def\">surveillance</span> + <span class=\"kw-def\">dépistage</span> de <span class=\"kw-etio\">myocardite</span>) et <span class=\"kw-etio\">épidermolyse staphylococcique</span>.<br><strong>USC / <span class=\"kw-alerte\">réanimation</span> :</strong> <span class=\"kw-alerte\">syndrome toxinique</span> streptococcique ou staphylococcique (apport hémodynamique).<br><strong>Ambulatoire :</strong> <span class=\"kw-etio\">scarlatine</span> non compliquée et exanthèmes viraux bénins (<span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">rubéole</span>, <span class=\"kw-etio\">roséole</span>, <span class=\"kw-etio\">mégalérythème</span>, <span class=\"kw-etio\">MNI</span>) — hospitalisation si <span class=\"kw-alerte\">signes de gravité</span> ou forme compliquée.</p>","redflags":"<ul><li><span class=\"kw-clinique\">Érythème</span> généralisé > <span class=\"kw-chiffre\">90 %</span> de la surface corporelle avec <span class=\"kw-clinique\">desquamation</span> constante = <span class=\"kw-alerte\">érythrodermie</span></li><li><span class=\"kw-alerte\">Troubles hémodynamiques</span> par déperdition hydro-électrolytique et protéique</li><li><span class=\"kw-clinique\">Dysrégulation thermique</span> : épisodes de <span class=\"kw-alerte\">fièvre</span> et d'<span class=\"kw-alerte\">hypothermie</span></li><li><span class=\"kw-clinique\">Décollement bulleux</span> superficiel avec <span class=\"kw-alerte\">signe de Nikolsky</span> (épidermolyse staphylococcique)</li><li><span class=\"kw-alerte\">Hypotension</span> + <span class=\"kw-alerte\">atteinte multiviscérale</span> (digestive, rénale, hépatique...) = <span class=\"kw-alerte\">choc toxique</span></li><li><span class=\"kw-clinique\">Fièvre</span> ≥ <span class=\"kw-chiffre\">5 jours</span> non réduite par les antipyrétiques (évoquer <span class=\"kw-etio\">Kawasaki</span>)</li><li>Complications cardiovasculaires du Kawasaki : <span class=\"kw-etio\">myocardite</span>, <span class=\"kw-etio\">anévrismes coronaires</span></li><li><span class=\"kw-clinique\">Œdème du visage</span> avec <span class=\"kw-clinique\">ectropion</span>, polyadénopathie et <span class=\"kw-clinique\">altération de l'état général</span></li></ul>","principes":"<p>Distinguer l'<span class=\"kw-alerte\">urgence</span> (érythrodermie, Kawasaki, syndrome toxinique) du traitement <span class=\"kw-ttt\">symptomatique</span> ambulatoire des exanthèmes viraux bénins.</p><p><strong>Érythrodermie (<span class=\"kw-alerte\">urgence</span>)</strong></p><p>Étiologies à traquer : <span class=\"kw-etio\">psoriasis</span>, <span class=\"kw-etio\">eczéma/dermatite atopique</span>, <span class=\"kw-etio\">toxidermie (DRESS)</span>, <span class=\"kw-etio\">syndrome de Sézary</span>, <span class=\"kw-etio\">gale croûteuse</span></p><ul><li><span class=\"kw-ttt\">Hospitalisation en urgence</span> avec <span class=\"kw-bio\">bilan biologique</span> de gravité</li><li><span class=\"kw-ttt\">Rééquilibration des troubles hydro-électrolytiques</span> et traitement des défaillances viscérales</li><li><span class=\"kw-ttt\">Réchauffer le malade</span> pour limiter l'hypercatabolisme et la dénutrition</li><li>Formes graves : <span class=\"kw-ttt\">corticothérapie locale de niveau 1</span> (très forte)</li><li>Recherche étiologique : <span class=\"kw-bio\">biopsie cutanée</span>, répétée si suspicion de <span class=\"kw-etio\">lymphome cutané</span></li></ul><p><strong>Exanthèmes viraux bénins</strong></p><p>Pas d'éviction obligatoire pour la <span class=\"kw-etio\">roséole</span>, le <span class=\"kw-etio\">mégalérythème</span> ni la <span class=\"kw-etio\">MNI</span></p><ul><li>PEC <span class=\"kw-ttt\">ambulatoire symptomatique</span> : <span class=\"kw-ttt\">paracétamol</span> pour la <span class=\"kw-clinique\">fièvre</span></li><li><span class=\"kw-ttt\">Antibiothérapie</span> réservée aux surinfections bactériennes</li><li><span class=\"kw-etio\">Rougeole</span> et <span class=\"kw-etio\">rubéole</span> : <span class=\"kw-ttt\">déclaration obligatoire</span></li><li><span class=\"kw-etio\">Rougeole</span> : éviction de collectivité jusqu'à <span class=\"kw-chiffre\">5 jours</span> après le début de l'<span class=\"kw-clinique\">éruption</span></li></ul><p><strong>Scarlatine (SGA)</strong></p><p>Aucun <span class=\"kw-def\">suivi</span> : pas de recherche d'<span class=\"kw-bio\">hématurie</span>/<span class=\"kw-bio\">protéinurie</span> à distance</p><ul><li><span class=\"kw-bio\">TDR streptocoque A</span> systématique avant antibiotique</li><li><span class=\"kw-ttt\">Amoxicilline</span> per os pendant <span class=\"kw-chiffre\">6 jours</span></li><li>Éviction de collectivité jusqu'à <span class=\"kw-chiffre\">48 h</span> d'<span class=\"kw-ttt\">antibiothérapie</span></li></ul><p><strong>Maladie de Kawasaki</strong></p><p><span class=\"kw-def\">Surveillance</span> <span class=\"kw-imagerie\">échocardiographique</span> (<span class=\"kw-imagerie\">ETT</span>) systématique</p><ul><li><span class=\"kw-ttt\">Hospitalisation</span> indispensable en phase aiguë</li><li><span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span> pour stopper l'inflammation et prévenir les atteintes cardiaques</li><li><span class=\"kw-ttt\">Aspirine</span> : dose anti-<span class=\"kw-etio\">inflammatoire</span> en phase aiguë puis faible dose anti-agrégante pendant <span class=\"kw-chiffre\">≥ 6 à 8 semaines</span></li></ul><p><strong>Épidermolyse staphylococcique (SSSS)</strong></p><p><span class=\"kw-alerte\">Choc toxique staphylococcique</span> → USC / <span class=\"kw-alerte\">réanimation</span></p><ul><li><span class=\"kw-ttt\">Hospitalisation</span> + <span class=\"kw-ttt\">pénicilline M (oxacilline)</span>, <span class=\"kw-ttt\">clindamycine</span> ou <span class=\"kw-ttt\">vancomycine</span> si SARM</li><li><span class=\"kw-ci\">Corticoïdes contre-indiqués</span></li><li>Éviction scolaire jusqu'à <span class=\"kw-chiffre\">48 h</span> de traitement</li></ul>","suivi":"<p><strong>Érythrodermie :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">hydro-électrolytique</span> et <span class=\"kw-def\">dépistage</span> des <span class=\"kw-alerte\">complications infectieuses</span> (cutanées, urinaires, pneumopathie, septicémie) ; <span class=\"kw-bio\">biopsie</span> répétée si suspicion de <span class=\"kw-etio\">lymphome</span>.<br><strong>Kawasaki :</strong> surveillance <span class=\"kw-imagerie\">échocardiographique</span> répétée ; <span class=\"kw-ttt\">aspirine</span> poursuivie <span class=\"kw-chiffre\">≥ 6 à 8 semaines</span> et tant qu'il existe des lésions coronariennes.<br><strong>Scarlatine :</strong> aucun <span class=\"kw-def\">suivi</span> systématique.<br><strong>Femme enceinte :</strong> contage par <span class=\"kw-etio\">rubéole</span>, <span class=\"kw-etio\">parvovirus B19</span>, <span class=\"kw-etio\">toxoplasmose</span> ou <span class=\"kw-etio\">syphilis</span> → <span class=\"kw-bio\">sérologies</span> et surveillance spécialisée (risque fœtal).</p>"},"liensGlobaux":[{"href":"https://fr.wikipedia.org/wiki/Ligne_de_Beau","label":"Wikipedia — Ligne de Beau (sillon transverse unguéal)"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-217.pdf","label":"Collège Pilly — Item 217 (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Éruption érythémateuse fébrile — Exanthème ou érythrodermie","detail":"<h4>CAT — <span class=\"kw-clinique\">Éruption</span> fébrile : exanthème ou érythrodermie — Trier l'<span class=\"kw-alerte\">urgence</span> avant d'orienter selon le type et le contexte</h4>","branches":[{"to":"q-erythro","label":"Éruption fébrile","color":"blue"}]},{"id":"q-erythro","kind":"decision","label":"Érythème confluant + desquamation sur > 90 % du corps, évoluant depuis ≥ 6 semaines ?","branches":[{"to":"t-erythro","label":"Oui","color":"red"},{"to":"q-grav","label":"Non","color":"blue"}]},{"id":"t-erythro","kind":"terminal","label":"Érythrodermie — hospitalisation en urgence","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Hospitalisation en urgence</span> avec <span class=\"kw-bio\">bilan biologique</span> de gravité</li><li>Recherche étiologique : <span class=\"kw-bio\">biopsie cutanée</span>, répétée si suspicion de <span class=\"kw-etio\">lymphome</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Rééquilibration hydro-électrolytique</span> + traitement des défaillances viscérales</li><li><span class=\"kw-ttt\">Réchauffement</span> du malade ; formes graves : <span class=\"kw-ttt\">corticothérapie locale niveau 1</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Dépister les <span class=\"kw-alerte\">complications infectieuses</span> (<span class=\"kw-def\">mortalité</span> jusqu'à <span class=\"kw-chiffre\">20 %</span>)</li></ul>"},{"id":"q-grav","kind":"decision","label":"Décollement bulleux (signe de Nikolsky), hypotension ou atteinte multiviscérale ?","branches":[{"to":"t-toxinique","label":"Oui","color":"red"},{"to":"q-kawa","label":"Non","color":"blue"}]},{"id":"t-toxinique","kind":"terminal","label":"Syndrome toxinique (SSSS / choc toxique) — hospitalisation, USC-réa si choc","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Décollement bulleux</span> superficiel avec <span class=\"kw-alerte\">signe de Nikolsky</span></li><li>Début aux <span class=\"kw-clinique\">grands plis</span> et régions <span class=\"kw-clinique\">péri-orificielles</span>, sans <span class=\"kw-clinique\">atteinte muqueuse</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Pénicilline M (oxacilline)</span>, <span class=\"kw-ttt\">clindamycine</span> ou <span class=\"kw-ttt\">vancomycine</span> si SARM</li><li><span class=\"kw-ci\">Corticoïdes contre-indiqués</span> ; <span class=\"kw-alerte\">choc</span> → USC / <span class=\"kw-alerte\">réanimation</span></li></ul>"},{"id":"q-kawa","kind":"decision","label":"Fièvre ≥ 5 jours résistante aux antipyrétiques + ≥ 4/5 critères (conjonctivite, énanthème, éruption, extrémités, adénopathie) ?","branches":[{"to":"t-kawa","label":"Oui","color":"red"},{"to":"q-scarlat","label":"Non","color":"blue"}]},{"id":"t-kawa","kind":"terminal","label":"Maladie de Kawasaki — hospitalisation indispensable + ETT","color":"red","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">VS</span>), <span class=\"kw-bio\">hyperleucocytose à PNN</span>, <span class=\"kw-bio\">thrombocytose</span>, <span class=\"kw-bio\">leucocyturie amicrobienne</span></li><li><span class=\"kw-imagerie\">ETT</span> systématique (<span class=\"kw-def\">dépistage</span> de l'atteinte coronarienne)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Immunoglobulines polyvalentes IV</span></li><li><span class=\"kw-ttt\">Aspirine</span> : anti-<span class=\"kw-etio\">inflammatoire</span> puis anti-agrégante (<span class=\"kw-chiffre\">≥ 6 à 8 semaines</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Complications cardiovasculaires : <span class=\"kw-etio\">myocardite</span>, <span class=\"kw-etio\">anévrismes coronaires</span></li></ul>"},{"id":"q-scarlat","kind":"decision","label":"Exanthème scarlatiniforme + angine fébrile, TDR streptocoque A positif ?","branches":[{"to":"t-scarlat","label":"Oui","color":"green"},{"to":"t-viral","label":"Non","color":"green"}]},{"id":"t-scarlat","kind":"terminal","label":"Scarlatine — ambulatoire, amoxicilline 6 jours","color":"green","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">TDR streptocoque A</span> systématique avant antibiotique</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> per os pendant <span class=\"kw-chiffre\">6 jours</span></li><li>Éviction de collectivité jusqu'à <span class=\"kw-chiffre\">48 h</span> d'<span class=\"kw-ttt\">antibiothérapie</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Aucun <span class=\"kw-def\">suivi</span> (pas de recherche d'<span class=\"kw-bio\">hématurie</span>/<span class=\"kw-bio\">protéinurie</span>)</li><li><span class=\"kw-alerte\">Hospitalisation</span> seulement si <span class=\"kw-alerte\">syndrome toxinique</span> (USC/réa)</li></ul>"},{"id":"t-viral","kind":"terminal","label":"Exanthème viral présumé bénin — ambulatoire, symptomatique","color":"green","detail":"<h4>Conduite</h4><ul><li>PEC <span class=\"kw-ttt\">ambulatoire symptomatique</span> : <span class=\"kw-ttt\">paracétamol</span> ; <span class=\"kw-ttt\">antibiotique</span> seulement si surinfection <span class=\"kw-etio\">bactérienne</span></li><li>Orienter selon type/contexte : <span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">rubéole</span>, <span class=\"kw-etio\">roséole</span>, <span class=\"kw-etio\">mégalérythème</span>, <span class=\"kw-etio\">MNI</span></li><li><span class=\"kw-ttt\">Déclaration obligatoire</span> + éviction <span class=\"kw-chiffre\">5 jours</span> si <span class=\"kw-etio\">rougeole</span> ; déclaration si <span class=\"kw-etio\">rubéole</span></li></ul><h4>Délai</h4><ul><li>Femme enceinte : <span class=\"kw-bio\">sérologies</span> (<span class=\"kw-etio\">rubéole</span>, <span class=\"kw-etio\">parvovirus B19</span>, <span class=\"kw-etio\">toxoplasmose</span>, <span class=\"kw-etio\">syphilis</span>) — risque fœtal</li><li>Hospitaliser si <span class=\"kw-alerte\">signes de gravité</span> ou forme compliquée</li></ul>"}]},"cards":[{"i":"7f3d0f9464b5","n":114,"o":"114-1","u":"Définition","t":"Connaître la définition d’un exanthème","q":"Quelle est la définition d'un exanthème ?","a":"<p>Un exanthème est un <strong>érythème d’apparition brutale et transitoire</strong>, lié à une <strong>vasodilatation vasculaire</strong>, qui s’efface à la vitropression.</p>"},{"i":"c751bcaa7324","n":114,"o":"114-1","u":"Définition","t":"Connaître la définition d’un exanthème","q":"Comment évaluer la gravité d'un exanthème ?","a":"<p>Bien que le plus souvent <strong>bénin</strong>, un exanthème peut être potentiellement grave. Il faut notamment rechercher des signes évocateurs de <strong>toxidermie</strong>, <strong>méningococcémie</strong>, maladie de <strong>Kawasaki</strong>, ou <strong>choc toxinique</strong>.</p>"},{"i":"e794d1ce5c77","n":114,"o":"114-1","u":"Définition","t":"Connaître la définition d’un exanthème","q":"Quelles sont les caractéristiques sémiologiques d'un exanthème ?","a":"<ul><li>Son intensité est <strong>variable</strong>.</li><li>Il peut être <strong>diffus</strong> ou avoir une <strong>topographie spécifique</strong>.</li><li>Il peut être isolé ou associé à une symptomatologie variée.</li></ul>"},{"i":"f57876d7a943","n":114,"o":"114-1","u":"Définition","t":"Connaître la définition d’un exanthème","q":"Qu'est-ce qu'un énanthème et à quoi peut-il être associé ?","a":"<p>Un énanthème correspond à une <strong>atteinte muqueuse</strong>, qui peut être associée à un exanthème. Des exemples incluent le <strong>purpura du voile du palais</strong>, la <strong>glossite</strong>, la <strong>chéilite</strong> ou la <strong>langue framboisée</strong>.</p>"},{"i":"4ef8bc0fa9d5","n":114,"o":"114-10","u":"Étiologies","t":"Connaître la principale cause d’exanthème chez l’enfant et chez l’adulte","q":"Quelle est la principale cause d'exanthème chez l'adulte ?","a":"<p>Chez l'adulte, la principale cause d'exanthème est représentée par les <strong>toxidermies médicamenteuses</strong>. Il faut également systématiquement évoquer les <strong>infections sexuellement transmissibles (IST)</strong>, notamment :</p><ul><li>La <strong>syphilis</strong></li><li>La <strong>primo-infection VIH</strong></li></ul>"},{"i":"a53cd5e48f71","n":114,"o":"114-10","u":"Étiologies","t":"Connaître la principale cause d’exanthème chez l’enfant et chez l’adulte","q":"Quelle est la principale cause d'exanthème chez l'enfant ?","a":"<p>Chez l'enfant, la principale cause d'exanthème est d'<strong>origine virale</strong>. On retrouve notamment :</p><ul><li>La <strong>rougeole</strong></li><li>L'<strong>exanthème subit</strong> (roséole infantile)</li><li>Le <strong>mégalérythème épidémique</strong> (cinquième maladie due au parvovirus B19)</li><li>La <strong>rubéole</strong></li><li>Les <strong>entérovirus</strong></li></ul><p>Les <strong>toxidermies maculo-papuleuses</strong> médicamenteuses sont également une cause possible.</p>"},{"i":"ad3d60cb509f","n":114,"o":"114-10","u":"Étiologies","t":"Connaître la principale cause d’exanthème chez l’enfant et chez l’adulte","q":"Pour quelle catégorie de patient un exanthème doit-il faire évoquer une IST ?","a":"<p>Chez l'<strong>adulte</strong>, un exanthème doit systématiquement faire évoquer une <strong>IST</strong>, principalement la <strong>syphilis</strong> et la <strong>primo-infection VIH</strong>, en plus des causes médicamenteuses.</p>"},{"i":"0ee19cd95d59","n":114,"o":"114-16","u":"Étiologies","t":"Savoir évoquer une rougeole chez l’enfant et chez l’adulte","q":"Quelles sont les principales complications infectieuses et neurologiques de la rougeole ?","a":"<p>Les complications infectieuses, souvent associées à une réascension thermique, incluent la <strong>bronchite</strong>, la <strong>pneumopathie</strong>, la <strong>surinfection pulmonaire</strong> et l'<strong>OMA purulente</strong>. Les complications neurologiques sont :</p><ul><li>L'<strong>encéphalite aiguë morbilleuse post-éruptive</strong> (1/1 000).</li><li>La <strong>panencéphalite sclérosante subaiguë de Van Bogaert (PESS)</strong>, retardée de 5 à 10 ans (1/100 000, ou 1/6 000 si rougeole < 1 an).</li></ul>"},{"i":"6f9cd82c4bce","n":114,"o":"114-16","u":"Étiologies","t":"Savoir évoquer une rougeole chez l’enfant et chez l’adulte","q":"Comment la rougeole est-elle biologiquement confirmée et quand doit-elle être déclarée ?","a":"<p>La confirmation biologique est systématique. Elle peut se faire par :</p><ul><li><strong>PCR</strong> (méthode directe) sur salive, nez, gorge, sang ou urine, optimale de J0 à J5 (jusqu'à J12).</li><li><strong>Sérologie IgM</strong> (méthode indirecte) sur salive ou sérum, optimale de J3 à J28 (jusqu'à J60).</li></ul><p>La rougeole est une <strong>maladie à déclaration obligatoire</strong> à l'ARS sans délai.</p>"},{"i":"e33b9c299849","n":114,"o":"114-16","u":"Étiologies","t":"Savoir évoquer une rougeole chez l’enfant et chez l’adulte","q":"Décrivez les caractéristiques de l'exanthème morbilliforme de la rougeole.","a":"<p>L'exanthème morbilliforme de la rougeole est <strong>non prurigineux</strong> et respectant des intervalles de peau saine. Ses caractéristiques sont :</p><ul><li>Il débute en <strong>rétro-auriculaire</strong>.</li><li>Il présente une extension <strong>descendante</strong> vers le visage et le reste du corps.</li><li>Il apparaît en <strong>une seule poussée</strong> sur 24 à 48 heures.</li><li>Il régresse en 5 à 6 jours.</li></ul>"},{"i":"e649c6c1178e","n":114,"o":"114-16","u":"Étiologies","t":"Savoir évoquer une rougeole chez l’enfant et chez l’adulte","q":"Quels sont les signes cliniques caractéristiques de la phase d'invasion (catarrhale) de la rougeole ?","a":"<p>La phase d'invasion, qui dure 2 à 4 jours, se caractérise par :</p><ul><li>Une <strong>fièvre élevée</strong> (39-40 °C).</li><li>Un <strong>catarrhe oculo-respiratoire</strong> : larmoiement, conjonctivite, rhinorrhée, toux.</li><li>Le <strong>signe de Köplik</strong> (pathognomonique) : taches punctiformes blanc-bleuté sur muqueuse jugale inflammatoire.</li></ul>"},{"i":"faf69ff66d32","n":114,"o":"114-16","u":"Étiologies","t":"Savoir évoquer une rougeole chez l’enfant et chez l’adulte","q":"Comment un nourrisson peut-il être protégé contre la rougeole avant l'âge de 6 mois et quels sont les terrains à risque d'une forme grave ?","a":"<p>Les nourrissons sont protégés jusqu'à <strong>6 mois</strong> par les <strong>anticorps maternels</strong>. Les terrains à risque de rougeole grave sont les nourrissons <strong>< 1 an</strong>, les <strong>adultes</strong> (notamment > 20 ans), les <strong>femmes enceintes</strong> et les <strong>immunodéprimés</strong>.</p>"},{"i":"6b2d844b1d45","n":114,"o":"114-17","u":"Étiologies","t":"Connaître trois causes d’érythrodermie chez l’adulte","q":"Quelle est une cause potentiellement grave d'érythrodermie chez l'adulte liée à une réaction médicamenteuse ?","a":"<p>Une cause potentiellement grave d'érythrodermie chez l'adulte, liée à une réaction médicamenteuse, est représentée par les <strong>Toxidermies</strong>, notamment le <strong>DRESS</strong> (Drug Reaction with Eosinophilia and Systemic Symptoms).</p>"},{"i":"f6d1ce7b937b","n":114,"o":"114-17","u":"Étiologies","t":"Connaître trois causes d’érythrodermie chez l’adulte","q":"Quelle est l'étiologie la plus fréquente d'érythrodermie chez l'adulte, relevant des dermatoses inflammatoires ?","a":"<p>La cause la plus fréquente d'érythrodermie chez l'adulte, relevant des dermatoses inflammatoires, est le <strong>Psoriasis</strong>.</p>"},{"i":"f785103f1503","n":114,"o":"114-17","u":"Étiologies","t":"Connaître trois causes d’érythrodermie chez l’adulte","q":"En dehors du psoriasis érythrodermique, quelle autre dermatose inflammatoire est une cause majeure d'érythrodermie chez l'adulte ?","a":"<p>Une autre cause majeure d'érythrodermie chez l'adulte est la <strong>Dermatite atopique</strong> ou <strong>eczéma érythrodermique</strong>.</p>"},{"i":"ff02a3f671d7","n":114,"o":"114-17","u":"Étiologies","t":"Connaître trois causes d’érythrodermie chez l’adulte","q":"Quel type d'hémopathie maligne peut s'exprimer par une érythrodermie chez l'adulte ?","a":"<p>Un <strong>lymphome T cutané épidermotrope</strong>, tel que le <strong>syndrome de Sézary</strong>, peut être une cause d'érythrodermie chez l'adulte. Une <strong>biopsie cutanée</strong> est essentielle pour le diagnostic.</p>"},{"i":"0a38dc80c414","n":114,"o":"114-19","u":"Contenu multimédia","t":"Photographie d’un exanthème morbilliforme","q":"Quelle est la sémiologie dermatologique caractéristique d'un exanthème morbilliforme ?","a":"<p>Un exanthème morbilliforme se caractérise par :</p><ul><li>Des éruptions <strong>maculo-papuleuses rouges</strong>.</li><li>Un <strong>léger relief palpable</strong>.</li><li>Des <strong>plaques</strong> qui peuvent confluer en placards.</li><li>Des <strong>intervalles de peau saine</strong> préservés entre les lésions.</li></ul>"},{"i":"4a322461b776","n":114,"o":"114-19","u":"Contenu multimédia","t":"Photographie d’un exanthème morbilliforme","q":"Quelles sont les principales étiologies à évoquer devant un exanthème morbilliforme suspecté sur photographie clinique ?","a":"<p>Les principales étiologies à évoquer devant un exanthème morbilliforme sont :</p><ul><li>La <strong>rougeole</strong> (paramyxovirus), où il faut rechercher un signe de Köplik associé.</li><li>Le <strong>mégalérythème épidémique</strong> (Parvovirus B19), avec les joues souffletées.</li><li>La <strong>mononucléose infectieuse</strong> (EBV), souvent associée à un rash après prise d'ampicilline.</li><li>Une <strong>toxidermie maculo-papuleuse</strong>.</li><li>Une <strong>primo-infection VIH</strong>.</li></ul>"},{"i":"b8b775232648","n":114,"o":"114-19","u":"Contenu multimédia","t":"Photographie d’un exanthème morbilliforme","q":"Comment évolue typiquement un exanthème morbilliforme dans le cas de la rougeole ?","a":"<p>Dans le cas d'une rougeole typique, l'exanthème morbilliforme présente une <strong>évolution descendante</strong>, débutant au niveau <strong>rétro-auriculaire</strong>, puis progressant vers le <strong>visage</strong>, le <strong>tronc</strong> et enfin les <strong>membres</strong>.</p>"},{"i":"1f5971b39737","n":114,"o":"114-20","u":"Contenu multimédia","t":"Photographie d’un exanthème scarlatiniforme","q":"Comment évolue un exanthème scarlatiniforme et quelles sont les principales étiologies à évoquer ?","a":"<p>L'exanthème scarlatiniforme évolue vers une <strong>desquamation post-éruptive « en doigt de gant »</strong> des extrémités à partir de J6. Les principales étiologies à évoquer sont :</p><ul><li>La <strong>Scarlatine</strong> (due au Streptocoque du groupe A produisant une toxine érythrogène, souvent associée à une angine et une glossite).</li><li>L'<strong>épidermolyse staphylococcique</strong> (sans angine, avec signe de Nikolsky).</li><li>La <strong>maladie de Kawasaki</strong> (une forme scarlatiniforme est possible).</li><li>Une <strong>toxidermie médicamenteuse</strong>.</li></ul>"},{"i":"53a264414127","n":114,"o":"114-20","u":"Contenu multimédia","t":"Photographie d’un exanthème scarlatiniforme","q":"Comment décrire l'aspect visuel de l'exanthème scarlatiniforme sur une photographie ?","a":"<p>Sur une photographie, l'exanthème scarlatiniforme se présente sous la forme de <strong>vastes nappes rouge vif</strong> ou sombre, <strong>uniformes et congestives</strong>, sans intervalle de peau saine.</p>"},{"i":"e750367b1bb1","n":114,"o":"114-20","u":"Contenu multimédia","t":"Photographie d’un exanthème scarlatiniforme","q":"Quelles sont les caractéristiques palpatoires et la topographie typique d'un exanthème scarlatiniforme ?","a":"<p>À la palpation, l'exanthème scarlatiniforme est <strong>granité</strong>. Sa topographie prédomine aux <strong>grands plis</strong>, s'étend à la partie inférieure de l'abdomen et aux extrémités (avec <strong>respect des paumes et plantes</strong>), et au visage (avec <strong>respect péri-buccal</strong>).</p>"},{"i":"3d57fe320e37","n":114,"o":"114-21","u":"Contenu multimédia","t":"Photographie d’une érythrodermie","q":"Quels sont les signes dermatologiques caractéristiques d'une érythrodermie ?","a":"<ul><li><strong>Érythème généralisé</strong>, inflammatoire, parfois plus <strong>violacé</strong> aux zones déclives.</li><li><strong>Desquamation constante</strong>, fine ou en larges lambeaux.</li><li><strong>Pachydermie</strong> (épaississement de la peau), prédominant aux plis.</li><li><strong>Œdème du visage</strong>, pouvant entraîner un <strong>ectropion</strong> (éversion de la muqueuse palpébrale).</li></ul>"},{"i":"3fd80abb193f","n":114,"o":"114-21","u":"Contenu multimédia","t":"Photographie d’une érythrodermie","q":"Quelles sont les atteintes annexielles et l'examen général associées à l'érythrodermie ?","a":"<ul><li><strong>Atteinte des phanères</strong> après quelques semaines : chute des cheveux, sourcils et cils ; ongles dystrophiques, ligne de Beau, voire chute de l'ongle.</li><li>Atteinte muqueuse : <strong>chéilite</strong> (inflammation des lèvres), <strong>conjonctivite</strong>, <strong>stomatite</strong> (inflammation de la muqueuse buccale).</li><li>Présence fréquente de <strong>polyadénopathies</strong> (ganglions de grande taille, souples et mobiles).</li></ul>"},{"i":"95554dcf0821","n":114,"o":"114-21","u":"Contenu multimédia","t":"Photographie d’une érythrodermie","q":"Quelle est la définition clinique d'une érythrodermie ?","a":"<p>Une érythrodermie est un <strong>érythème confluant</strong> et une <strong>desquamation</strong> qui affectent <strong>plus de 90 % de la surface corporelle</strong>, avec une évolution <strong>prolongée de plus de 6 semaines</strong>.</p>"},{"i":"077c6a8a68a6","n":114,"o":"114-3","u":"Diagnostic positif","t":"Savoir reconnaître les trois types séméiologiques d’exanthème","q":"Quelles sont les caractéristiques d'un exanthème roséoliforme (ou rubéoliforme) ?","a":"<p>L'exanthème roséoliforme est composé de <strong>macules</strong> de couleur <strong>rosée ou pâle</strong>, qui sont généralement <strong>sans relief ou avec un relief minime</strong>. Les lésions sont <strong>séparées les unes des autres par des intervalles de peau saine</strong>.</p>"},{"i":"b3d141b78c09","n":114,"o":"114-3","u":"Diagnostic positif","t":"Savoir reconnaître les trois types séméiologiques d’exanthème","q":"Comment reconnaît-on cliniquement un exanthème morbilliforme ?","a":"<p>L'exanthème morbilliforme se caractérise par des lésions <strong>maculo-papuleuses</strong> de couleur <strong>rouge</strong> et légèrement papuleuses ou en relief. Ces lésions sont souvent polymorphes, peuvent confluer en plaques plus larges, mais <strong>conservent des intervalles de peau saine</strong>.</p>"},{"i":"e66b8809853b","n":114,"o":"114-3","u":"Diagnostic positif","t":"Savoir reconnaître les trois types séméiologiques d’exanthème","q":"Décrivez les particularités cliniques d'un exanthème scarlatiniforme.","a":"<p>L'exanthème scarlatiniforme est constitué de <strong>plaques ou nappes diffuses</strong> de couleur <strong>rouge vif ou plus sombre</strong>. La peau est souvent <strong>légèrement granitée à la palpation</strong>, et surtout, l'éruption est <strong>d'un seul tenant, sans intervalle de peau saine</strong>.</p>"},{"i":"2018e6d62c21","n":114,"o":"114-6","u":"Diagnostic positif","t":"Connaître les complications systémiques de l’érythrodermie","q":"Quelles sont les complications infectieuses de l'érythrodermie ?","a":"<p>Les complications infectieuses de l'érythrodermie peuvent être :</p><ul><li><strong>Infections cutanées</strong> : bactériennes (notamment à <strong>staphylocoque</strong>) ; virales (<strong>herpès</strong>, <strong>varicelle</strong>).</li><li><strong>Infections générales</strong> : urinaires (fréquentes), pneumopathie, <strong>septicémie</strong>.</li></ul>"},{"i":"91cdf50ddf9f","n":114,"o":"114-6","u":"Diagnostic positif","t":"Connaître les complications systémiques de l’érythrodermie","q":"Quelles sont les autres complications systémiques majeures de l'érythrodermie ?","a":"<p>Les autres complications systémiques majeures de l'érythrodermie incluent :</p><ul><li>Des complications de <strong>décubitus</strong> : escarres, thrombose veineuse profonde (<strong>TVP</strong>).</li><li>Une <strong>dérégulation thermique</strong> importante (fièvre et hypothermie).</li><li>Des <strong>troubles hémodynamiques</strong>.</li><li>Une <strong>décompensation</strong> cardiaque, respiratoire ou rénale.</li></ul>"},{"i":"97ecfc724f7e","n":114,"o":"114-6","u":"Diagnostic positif","t":"Connaître les complications systémiques de l’érythrodermie","q":"Quels sont les principaux types de complications hydro-électrolytiques et nutritionnelles de l'érythrodermie ?","a":"<p>Les principales complications hydro-électrolytiques et nutritionnelles de l'érythrodermie sont :</p><ul><li>Une <strong>déshydratation par déperdition hydro-électrolytique</strong>.</li><li>Des carences protéiques (<strong>dénutrition</strong>, <strong>cachexie</strong>).</li><li>Des carences en <strong>oligo-éléments</strong> (fer, zinc, vitamines).</li></ul>"},{"i":"a74287cfb24d","n":114,"o":"114-6","u":"Diagnostic positif","t":"Connaître les complications systémiques de l’érythrodermie","q":"Quel est le pronostic de l'érythrodermie et à quoi est principalement liée sa mortalité ?","a":"<p>L'érythrodermie est une urgence vitale avec une mortalité pouvant atteindre <strong>20 %</strong>. Cette mortalité est surtout liée à une <strong>complication infectieuse</strong>.</p>"},{"i":"d272c5721cdd","n":114,"o":"114-6","u":"Diagnostic positif","t":"Connaître les complications systémiques de l’érythrodermie","q":"Quels sont les mécanismes expliquant les déperditions rencontrées dans l'érythrodermie ?","a":"<p>Les déperditions dans l'érythrodermie s'expliquent par :</p><ul><li>Une <strong>vasodilatation cutanée</strong>.</li><li>Une <strong>desquamation</strong> importante.</li><li>Un <strong>suintement</strong>.</li><li>Un <strong>œdème</strong>.</li><li>La <strong>fièvre</strong>.</li></ul>"},{"i":"13089f0d3881","n":114,"o":"114-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épidermolyse staphylococcique","q":"Comment définir l'épidermolyse staphylococcique et quel est son agent causal principal ?","a":"<p>L'épidermolyse staphylococcique, aussi appelée scarlatine staphylococcique, est une pathologie due à la sécrétion de toxines (<strong>exfoliatines A et B</strong> ou <strong>TSST1</strong>) par <em>Staphylococcus aureus</em>. Ces toxines ciblent la <strong>desmogléine 1</strong>, entraînant une lyse des desmosomes et un décollement cutané.</p>"},{"i":"6a8343a56cc3","n":114,"o":"114-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épidermolyse staphylococcique","q":"Quels sont les points clés de la présentation clinique de l'épidermolyse staphylococcique ?","a":"<ul><li>Il n'y a <strong>pas d'angine</strong> ni d'atteinte muqueuse.</li><li>Le contexte est celui d'une <strong>infection brutale</strong> avec fièvre et un foyer initial à <em>S. aureus</em> (impétigo, omphalite, otite externe).</li><li>L'éruption est en 2 temps : un <strong>exanthème scarlatiniforme</strong> débutant aux grands plis et régions péri-orificielles (ombilic ++), évoluant vers un <strong>décollement bulleux superficiel</strong> avec un <strong>signe de Nikolsky positif</strong>.</li></ul>"},{"i":"8ac2ab9e4713","n":114,"o":"114-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épidermolyse staphylococcique","q":"Comment pose-t-on le diagnostic de certitude de l'épidermolyse staphylococcique ?","a":"<p>Le diagnostic, essentiellement clinique, est confirmé bactériologiquement par des <strong>prélèvements bactériologiques</strong> sur le foyer infectieux initial (hémocultures, ECBU, ou biopsie selon le contexte).</p>"},{"i":"b969fd0b9bb2","n":114,"o":"114-7","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une épidermolyse staphylococcique","q":"Quels sont le terrain et le mode de contamination typiques de l'épidermolyse staphylococcique ?","a":"<p>Elle touche principalement les <strong>enfants de moins de 5 ans</strong> (nouveau-nés, nourrissons) et se voit également chez l'adulte immunodéprimé ou souffrant d'insuffisance rénale. La contamination se fait souvent par contact avec un adulte porteur sain, avec des épidémies possibles en crèche.</p>"},{"i":"2534711d013d","n":114,"o":"114-9","u":"Identifier une urgence","t":"Savoir que l’érythrodermie est une urgence et savoir la prendre en charge","q":"Quelle est la prise en charge initiale et générale d'une érythrodermie en urgence ?","a":"<p>La prise en charge initiale en urgence inclut :</p><ul><li><strong>Hospitalisation immédiate</strong> et systématique.</li><li>Réalisation d'un <strong>bilan biologique complet</strong> pour évaluer la gravité et rechercher des complications.</li><li><strong>Rééquilibration hydro-électrolytique</strong> avec apports IV.</li><li>Prise en charge du <strong>réchauffement</strong> pour limiter les pertes cataboliques et l'hypercatabolisme.</li><li>Traitement des éventuelles <strong>défaillances viscérales</strong> (cardiaque, respiratoire, rénale).</li></ul>"},{"i":"4c44abb08576","n":114,"o":"114-9","u":"Identifier une urgence","t":"Savoir que l’érythrodermie est une urgence et savoir la prendre en charge","q":"Pourquoi l'érythrodermie est-elle considérée comme une urgence dermatologique ?","a":"<p>L'érythrodermie est une urgence en raison de sa <strong>mortalité élevée</strong> (jusqu'à 20%), de la nécessité d'une <strong>hospitalisation systématique</strong> et d'une prise en charge thérapeutique et étiologique immédiate pour prévenir les complications graves.</p>"},{"i":"80290a29c1b9","n":114,"o":"114-9","u":"Identifier une urgence","t":"Savoir que l’érythrodermie est une urgence et savoir la prendre en charge","q":"Comment reconnaît-on cliniquement une érythrodermie ?","a":"<p>L'érythrodermie se caractérise par :</p><ul><li>Un <strong>érythème confluant et une desquamation</strong> touchant <strong>plus de 90 %</strong> de la surface cutanée, évoluant depuis <strong>plus de 6 semaines</strong>.</li><li>Un <strong>prurit constant</strong> et une <strong>pachydermie</strong> (épaississement des plis).</li><li>Une <strong>atteinte muqueuse</strong> (énanthème, chéilite, conjonctivite).</li><li>Des atteintes des <strong>phanères</strong> après plusieurs semaines (chute de cheveux, sourcils, cils, ongles dystrophiques, lignes de Beau, onychomadèse).</li><li>Une <strong>polyadénopathie généralisée</strong>.</li><li>Un <strong>œdème du visage</strong>, pouvant entraîner un ectropion.</li></ul>"},{"i":"d375d70a35b1","n":114,"o":"114-9","u":"Identifier une urgence","t":"Savoir que l’érythrodermie est une urgence et savoir la prendre en charge","q":"Quel est le traitement symptomatique de l'érythrodermie et comment s'effectue la démarche étiologique ?","a":"<p>Le traitement symptomatique repose sur le <strong>réchauffement du patient</strong> pour limiter l'hypercatabolisme et la dénutrition. Pour les formes graves, on peut envisager une <strong>corticothérapie locale de niveau 1</strong> (très forte) pour améliorer rapidement les symptômes.</p><p>La démarche étiologique, menée en parallèle, implique :</p><ul><li>L'interrogatoire sur l'ancienneté de l'éruption, les <strong>antécédents dermatologiques</strong> et autres.</li><li>La recherche d'une <strong>prise médicamenteuse</strong> (DRESS, toxidermie) avec arrêt du médicament suspect.</li><li>L'analyse des traitements topiques utilisés.</li><li>La recherche d'un <strong>contexte infectieux</strong>.</li><li>Réaliser une <strong>biopsie cutanée</strong> (à répéter en cas de suspicion de lymphome cutané) et des <strong>prélèvements bactériologiques et parasitologiques</strong> si nécessaire.</li></ul>"}]};